sys_variable_value.value:
(function execute(inputs, outputs) {

    var archive = new AESCommunicationArchive();

    var archiveDate = archive.calculateArchiveDate(
        inputs.expiration_date,
        inputs.archive_after,
        inputs.archive_period_type
    );

    outputs.archive_date = archiveDate || '';

})(inputs, outputs);

